SELECT 'af5017e0-a8b9-5c94-958d-c11bbbdd6ca6'::uuid,'السيرة النبوية للمهندس علاء حامد','دروس الداعية المهندس علاء حامد','علاء حامد','المهندس علاء حامد، داعية ومقدم محتوى إسلامي، يقدم دروسًا وسلاسل صوتية في السيرة النبوية وقصص الصحابة والتربية الإيمانية.','b6393bd3-deea-403f-88af-f7ae0b34736c'::uuid,'religious','https://d3t3ozftmdmh3i.cloudfront.net/staging/podcast_uploaded_nologo/43212097/43212097-1742287421174-7b10abc67fb2a.jpg','beginner',(SELECT id FROM hosts WHERE name_ar='علاء حامد' LIMIT 1),0,0,NOW()
WHERE NOT EXISTS (SELECT 1 FROM podcasts WHERE title='السيرة النبوية للمهندس علاء حامد');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'وفاة الرسول صلى الله عليه وسلم _ بل الرفيق الأعلى_ ساعتين من البكاء😥_ السيرة النبوية (51)','هل شعرت يوماً أن أحداث السيرة النبوية مجرد سرد تاريخي بعيد عن واقعك وتحدياتك اليومية؟ في هذا البودكاست، يأخذنا المهندس والداعية علاء حامد في رحلة إيمانية وتربوية فريدة في ظلال السيرة النبوية العطرة، بأسلوب قصصي مشوق يلامس القلوب ويخاطب العقول. نحن لا نكتفي هنا بسرد الأحداث وتواريخ الغزوات، بل نغوص في أعماق المواقف لنستخرج منها الدروس والعبر، ونسقطها ببراعة على واقعنا المعاصر ومشاكل الشباب اليوم. من إرهاصات النبوة والعهد المكي المليء بتحديات الصبر والثبات، مروراً برحلة الهجرة، وصولاً إلى العهد المدني وبناء الأمة، نعيش مع النبي ﷺ وصحابته الكرام تفاصيل الحياة خطوة بخطوة. ماذا ستقدم لك هذه السلسلة؟ إسقاط واقعي وعملي: ربط مواقف السيرة بالتحديات النفسية، الاجتماعية، والمهنية التي نواجهها اليوم. أسلوب ممتع ومبسط: لغة سهلة وقريبة من القلب تجمع بين رصانة الفصحى وسلاسة التعبير، مما يجعلها مثالية للشباب والمبتدئين. بناء إيماني وتربوي: التركيز على الجانب العقائدي والأخلاقي، وكيفية الاقتداء العملي بأخلاق النبي ﷺ في شتى مناحي الحياة. رفيق في طريقك: سرد ماتع وأداء صوتي يمنحك السكينة، ليكون خير رفيق ل','https://anchor.fm/s/1022903e4/podcast/play/101802649/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-3-26%2Fab0cb152-239c-4714-75a3-0fbf03114216.mp3',7020,'2026-06-15T05:56:00'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/101802649/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-3-26%2Fab0cb152-239c-4714-75a3-0fbf03114216.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'حجة الوداع واقتربت النهاية😢مشاعر مؤثرة تعلم الحج مع النبي السيرة النبوية ( 50 )','هل شعرت يوماً أن أحداث السيرة النبوية مجرد سرد تاريخي بعيد عن واقعك وتحدياتك اليومية؟ في هذا البودكاست، يأخذنا المهندس والداعية علاء حامد في رحلة إيمانية وتربوية فريدة في ظلال السيرة النبوية العطرة، بأسلوب قصصي مشوق يلامس القلوب ويخاطب العقول. نحن لا نكتفي هنا بسرد الأحداث وتواريخ الغزوات، بل نغوص في أعماق المواقف لنستخرج منها الدروس والعبر، ونسقطها ببراعة على واقعنا المعاصر ومشاكل الشباب اليوم. من إرهاصات النبوة والعهد المكي المليء بتحديات الصبر والثبات، مروراً برحلة الهجرة، وصولاً إلى العهد المدني وبناء الأمة، نعيش مع النبي ﷺ وصحابته الكرام تفاصيل الحياة خطوة بخطوة. ماذا ستقدم لك هذه السلسلة؟ إسقاط واقعي وعملي: ربط مواقف السيرة بالتحديات النفسية، الاجتماعية، والمهنية التي نواجهها اليوم. أسلوب ممتع ومبسط: لغة سهلة وقريبة من القلب تجمع بين رصانة الفصحى وسلاسة التعبير، مما يجعلها مثالية للشباب والمبتدئين. بناء إيماني وتربوي: التركيز على الجانب العقائدي والأخلاقي، وكيفية الاقتداء العملي بأخلاق النبي ﷺ في شتى مناحي الحياة. رفيق في طريقك: سرد ماتع وأداء صوتي يمنحك السكينة، ليكون خير رفيق ل','https://anchor.fm/s/1022903e4/podcast/play/101491674/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-3-19%2F8455032f-488b-2273-427f-6d20ff146972.mp3',5726,'2026-06-14T17:56:00'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/101491674/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-3-19%2F8455032f-488b-2273-427f-6d20ff146972.mp3');
