SELECT p.id,'الدعوة السرية_ السيرة النبوية ( 10 )','هل شعرت يوماً أن أحداث السيرة النبوية مجرد سرد تاريخي بعيد عن واقعك وتحدياتك اليومية؟ في هذا البودكاست، يأخذنا المهندس والداعية علاء حامد في رحلة إيمانية وتربوية فريدة في ظلال السيرة النبوية العطرة، بأسلوب قصصي مشوق يلامس القلوب ويخاطب العقول. نحن لا نكتفي هنا بسرد الأحداث وتواريخ الغزوات، بل نغوص في أعماق المواقف لنستخرج منها الدروس والعبر، ونسقطها ببراعة على واقعنا المعاصر ومشاكل الشباب اليوم. من إرهاصات النبوة والعهد المكي المليء بتحديات الصبر والثبات، مروراً برحلة الهجرة، وصولاً إلى العهد المدني وبناء الأمة، نعيش مع النبي ﷺ وصحابته الكرام تفاصيل الحياة خطوة بخطوة. ماذا ستقدم لك هذه السلسلة؟ إسقاط واقعي وعملي: ربط مواقف السيرة بالتحديات النفسية، الاجتماعية، والمهنية التي نواجهها اليوم. أسلوب ممتع ومبسط: لغة سهلة وقريبة من القلب تجمع بين رصانة الفصحى وسلاسة التعبير، مما يجعلها مثالية للشباب والمبتدئين. بناء إيماني وتربوي: التركيز على الجانب العقائدي والأخلاقي، وكيفية الاقتداء العملي بأخلاق النبي ﷺ في شتى مناحي الحياة. رفيق في طريقك: سرد ماتع وأداء صوتي يمنحك السكينة، ليكون خير رفيق ل','https://anchor.fm/s/1022903e4/podcast/play/99562954/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-2-8%2F8dfe18e6-482a-bbe6-60b1-77ef0252b14f.mp3',4868,'2026-05-25T17:42:00'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/99562954/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-2-8%2F8dfe18e6-482a-bbe6-60b1-77ef0252b14f.mp3');
