SELECT p.id,'20 سبب لدراسة السيرة النبوية السيرة النبوية (1)','هل شعرت يوماً أن أحداث السيرة النبوية مجرد سرد تاريخي بعيد عن واقعك وتحدياتك اليومية؟ في هذا البودكاست، يأخذنا المهندس والداعية علاء حامد في رحلة إيمانية وتربوية فريدة في ظلال السيرة النبوية العطرة، بأسلوب قصصي مشوق يلامس القلوب ويخاطب العقول. نحن لا نكتفي هنا بسرد الأحداث وتواريخ الغزوات، بل نغوص في أعماق المواقف لنستخرج منها الدروس والعبر، ونسقطها ببراعة على واقعنا المعاصر ومشاكل الشباب اليوم. من إرهاصات النبوة والعهد المكي المليء بتحديات الصبر والثبات، مروراً برحلة الهجرة، وصولاً إلى العهد المدني وبناء الأمة، نعيش مع النبي ﷺ وصحابته الكرام تفاصيل الحياة خطوة بخطوة. ماذا ستقدم لك هذه السلسلة؟ إسقاط واقعي وعملي: ربط مواقف السيرة بالتحديات النفسية، الاجتماعية، والمهنية التي نواجهها اليوم. أسلوب ممتع ومبسط: لغة سهلة وقريبة من القلب تجمع بين رصانة الفصحى وسلاسة التعبير، مما يجعلها مثالية للشباب والمبتدئين. بناء إيماني وتربوي: التركيز على الجانب العقائدي والأخلاقي، وكيفية الاقتداء العملي بأخلاق النبي ﷺ في شتى مناحي الحياة. رفيق في طريقك: سرد ماتع وأداء صوتي يمنحك السكينة، ليكون خير رفيق ل','https://anchor.fm/s/1022903e4/podcast/play/99561353/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-2-8%2F59c68621-1d80-5e1d-d11f-082873c1b9e6.mp3',4263,'2026-05-21T05:26:36'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/99561353/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-2-8%2F59c68621-1d80-5e1d-d11f-082873c1b9e6.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'كونوا أنصار الله _ سورة الصف كما لم تسمعها من قبل ☝️ _ خد قرار واستجب _ دورة قد سمع ( 9 )','هل تبحث عن حلول قرآنية لمشاكلك اليومية؟ هل ترغب في فهم كلام الله وكأنه يتنزل لمعالجة واقعك الآن؟ مرحباً بك في بودكاست "مدرسة قد سمع" ، رحلة إيمانية وتربوية عميقة يصحبنا فيها الداعية المهندس علاء حامد . في هذه السلسلة، لا نكتفي بالتفسير النظري لسور الجزء الثامن والعشرين من القرآن الكريم (جزء قد سمع)، بل نغوص معاً لاستخراج "روشتات" عملية وواقعية تلامس حياتنا، وتصلح نفسياتنا، وتعالج علاقاتنا الأسرية والمجتمعية. من قصة "خولة بنت ثعلبة" التي سمع الله شكواها من فوق سبع سماوات، إلى معاني العزة في سورة الحشر، وقضايا الولاء والبراء في سورة الممتحنة؛ تأخذنا هذه السلسلة في بناء متكامل للفرد المسلم بأسلوب عصري، مبسط، وعميق في آن واحد. ماذا ستستفيد من هذه السلسلة؟ تدبر عملي: تحويل الآيات من مجرد تلاوة إلى منهج حياة وتطبيق يومي. إصلاح أسري ونفسي: استنباط حلول للمشاكل الزوجية والاجتماعية والقلق النفسي من داخل النص القرآني. تزكية ووعي: فهم أعمق لكيفية التعامل مع الأزمات، والمنافقين، وتحديات العصر بقلب مطمئن وعقيدة راسخة. استمع الآن، وابدأ رحلتك في تصحيح بوصلة حياتك بنور القرآن.','https://anchor.fm/s/1022903e4/podcast/play/118291073/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-3-11%2Fe48d0eb2-74f4-73bf-88d1-9135a14c44c3.mp3',4777,'2026-04-19T13:52:00'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/118291073/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-3-11%2Fe48d0eb2-74f4-73bf-88d1-9135a14c44c3.mp3');
