SELECT p.id,'بطل العالم ( سر الفوز بعشر ذي الحجة )','سلسلة علمية ودعوية تجمع بين الفكر والهداية ، يقدّمها المهندس علاء حامد بأسلوبٍ واقعيٍ مؤثرٍ يمزج بين الخطاب العقلي والروحاني.يتناول فيها قضايا متنوعة من الإيمان، والأخلاق، والتدبر في آيات الله، وتزكية النفس، وإحياء القلب ، مستمدًا المعاني من القرآن والسنة، وموجهًا رسالة صادقة إلى كل من يبحث عن النور وسط زحمة الحياة.الأسلوب يجمع بين البساطة والعمق ، فيعرض الدروس بقالبٍ عمليٍّ يناسب الشباب والناشئين، ويقود المستمع إلى فهم الدين بمعناه الشامل والرحمة التي جاء بها الإسلام. علاء حامد، دروس دينية، دروس إيمانية، محاضرات إسلامية، تزكية النفس، تدبر القرآن، دروس متنوعة، دروس تربوية، الإسلام الوسطي، خطب دعوية، الإيمان والعمل، هداية القلوب، الفكر الإسلامي، العلم والإيمان.','https://anchor.fm/s/1022903e4/podcast/play/111285228/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-10-17%2F566445a4-889b-0ea2-c52b-9bf914af110c.m4a',4284,'2025-11-17T06:59:40'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/111285228/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-10-17%2F566445a4-889b-0ea2-c52b-9bf914af110c.m4a');
