SELECT p.id,'شرح دعاء سيد الاستغفار( اللهم أنت ربي لا إله إلا أنت خلقتني ..)🤲 أفضل ختام جوامع الدعاء','"جوامع الدعاء" برنامج دعوي يقدّمه المهندس علاء حامد يشرح فيه الأدعية النبوية الجامعة؛ تلك الأدعية القصيرة في ألفاظها، العظيمة في معانيها، التي تشمل خيري الدنيا والآخرة. يقدّم السلسلة بلغة عربية فصيحة مبسّطة، تتيح للمشاهد فهم معاني الأدعية والتلذذ بمناجاة الله بها. الهدف هو ربط المسلم بالأدعية النبوية لتكون زادًا في حياته، واستشعار عظمة كلمات النبي ﷺ في الدعاء. #جوامع_الدعاء #الأدعية_النبوية #أدعية_مأثورة #الدعاء #علاء_حامد','https://anchor.fm/s/1022903e4/podcast/play/107956174/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-8-7%2Fe0801844-b81d-53ad-8d93-6d8cd7b2089b.m4a',1426,'2025-09-07T06:35:18'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/107956174/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-8-7%2Fe0801844-b81d-53ad-8d93-6d8cd7b2089b.m4a');
