SELECT p.id,'جوامع الأدب الدم الحرام 😮 قصة الدم دي خطيرة قوي الأربعين النووية (8) م علاء حامد','المهندس علاء حامد📖 نغوص في معاني كلام النبي ﷺ، بأسلوب سهل وهادئ، يجمع بين الفهم الصحيح، والربط العملي بحياتنا اليومية.🕌 نهدف في كل حلقة إلى تعزيز الوعي الشرعي، وترسيخ القيم التي جاء بها الإسلام في نفوسنا. #الأربعون_النووية #شرح_الأحاديث #حديث_شريف #علاء_حامد #السنة_النبوية #علم_ودين #حديث_وعبرة #ديننا_حياة #سلسلة_إسلامية #نور_الحديث #IslamicContent #HadithSeries','https://anchor.fm/s/1022903e4/podcast/play/107630192/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-8-1%2F27e77d7b-807d-10ca-0d94-6ee21e4e9341.m4a',4666,'2025-09-01T05:26:23'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/107630192/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-8-1%2F27e77d7b-807d-10ca-0d94-6ee21e4e9341.m4a');
