SELECT p.id,'تدبر سورة طه _ 10 _ وصايا النجاة','سلسلة إيمانية وتربوية ماتعة، يقدمها المهندس علاء حامد في تدبر سورة طه، بأسلوب سهل ومؤثر يربط الآيات بالواقع ويُظهر معاني الصبر والثبات في طريق الدعوة، مستلهمًا الدروس من قصة موسى عليه السلام مع فرعون وبني إسرائيل، ليعين المسلم على الثبات أمام الابتلاءات والتحديات. #تدبر #سورة_طه #علاء_حامد #قرآن #تفسير #إيمان #دعوة #صبر #ثبات #قصص_الأنبياء #تلاوة #علوم_القرآن','https://anchor.fm/s/1022903e4/podcast/play/107554287/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-7-30%2Fcb6161c9-7bdf-ba47-9e70-366bafc4047a.m4a',3943,'2025-08-30T05:35:22'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/107554287/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-7-30%2Fcb6161c9-7bdf-ba47-9e70-366bafc4047a.m4a');
