SELECT p.id,'المال الحرام 👎 قواعد الحياة السعيدة 🌷 درس سهل جدً مفيد جداً الأربعون النووية (7)','المهندس علاء حامد 📖 نغوص في معاني كلام النبي ﷺ، بأسلوب سهل وهادئ، يجمع بين الفهم الصحيح، والربط العملي بحياتنا اليومية.🕌 نهدف في كل حلقة إلى تعزيز الوعي الشرعي، وترسيخ القيم التي جاء بها الإسلام في نفوسنا. #الأربعون_النووية #شرح_الأحاديث #حديث_شريف #علاء_حامد #السنة_النبوية #علم_ودين #حديث_وعبرة #ديننا_حياة #سلسلة_إسلامية #نور_الحديث #IslamicContent #HadithSeries','https://anchor.fm/s/1022903e4/podcast/play/107236170/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-7-23%2F2ae31906-4f72-dc35-c64e-b694c4161bc7.m4a',4513,'2025-08-23T05:36:56'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/107236170/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-7-23%2F2ae31906-4f72-dc35-c64e-b694c4161bc7.m4a');
