SELECT p.id,'مسك الختام 💖_ ( آخر دروس سلسلة أنوار الكهف ) (14)','"أنوار الكهف" – سلسلة صوتية تدبرية يقدّمها المهندس علاء حامد ، نتأمل فيها معًا أعظم معاني سورة الكهف.عبر 14 حلقة ثرية، نغوص في قصصها العظيمة: أصحاب الكهف، صاحب الجنتين، موسى والخضر، وذي القرنين.نكتشف أسرار الفتن الأربع التي تكشفها السورة (فتنة الدين، فتنة المال، فتنة العلم، فتنة السلطة) وكيف نهتدي بنور الوحي لمواجهتها.بأسلوب قصصي مبسّط يجمع بين العمق والمعايشة، يأخذنا البودكاست في رحلة نورانية تُعيد صلتنا بالقرآن وتربط السورة بحياتنا اليومية.استمع إلى "أنوار الكهف" لتعيش مع سورة الكهف نورها، هداها، وبشائرها التي تحفظ الإيمان في زمن الفتن.#أنوار_الكهف','https://anchor.fm/s/1022903e4/podcast/play/107236078/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-7-23%2Ff5cca153-e994-4973-b649-dac04ba5bd5e.m4a',4475,'2025-08-23T05:35:13'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/107236078/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-7-23%2Ff5cca153-e994-4973-b649-dac04ba5bd5e.m4a');
