SELECT p.id,'لقد كان في قصصهم عبرة الدرس الأخير😢 خلاصة الفوائد مؤثر تعلمت من يوسف (14)','" تعلمت من يوسف عليه السلام " هي سلسلة تربوية معاصرة بأسلوب شيّق ومؤثر يقدمها المهندس علاء حامد. يأخذنا من خلالها في رحلة روحانية وعقلانية عبر الوقوف على معاني سورة يوسف، بدءًا من أسرار الحروف وتحول الأنفس، مرورًا ببطولة الصبر وتجاوز الفتنة، إلى الحكمة والدعوة. كل حلقة كأنها درس حياتي في فن التواصل مع الله وتربية النفس والشباب، بأسلوب يرنو إلى قلب كل مستمع!#تعلمت_من_يوسف #علاء_حامد #قصة_يوسف #تدبر_سورة_يوسف #دروس_إيمانية #فقه_السيرة #إلهام_شرعي #بودكاست_إسلامي #تربية_القلوب #الدروس_من_يوسف','https://anchor.fm/s/1022903e4/podcast/play/107000866/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-7-18%2F51955c8f-00f1-3f2a-8bb2-40de96b093e7.m4a',4988,'2025-08-18T06:13:30'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/107000866/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-7-18%2F51955c8f-00f1-3f2a-8bb2-40de96b093e7.m4a');
