SELECT p.id,'حجابك أمانة مشاهد مؤثرة وختام قوي لمدرسة الأحزاب الأحزاب ( 59 - 73 ) م علاء حامد','✨ الوصف المقترح لسلسلة "مدرسة الأحزاب": سلسلة "مدرسة الأحزاب" ليست مجرد تفسير لسورة عظيمة من سور القرآن، بل رحلة إيمانية وتربوية عميقة تقودك إلى فهم معنى الثبات وسط الزلازل، ومقام الحب الحقيقي للنبي ﷺ، ومعاني الصدق، والحياء، والجهاد، والطاعة، والتوبة . يقدمها المهندس علاء حامد بأسلوب تدبّري راقٍ، يمزج بين قوة المعاني ودفء التوجيه التربوي، بأسلوب يخاطب القلب والعقل معًا .في كل حلقة، ستشعر وكأنك ترى الآيات تنبض بالحياة، وكأنك تعيش زمن النبي ﷺ وتتعلم كيف تعيد ترتيب أولوياتك من جديد. هل أنت مستعد لأن تدخل مدرسة الحياة؟ مدرسة الأحزاب؟ #مدرسة_الأحزاب #علاء_حامد #تدبر_القرآن #سورة_الأحزاب #حب_النبي #غزوة_الخندق #الثبات #القرآن_حياة #دروس_قرآنية #سلفية_بروح_عصرية #تزكية_النفس #رحلة_إيمانية #سيرة_نبوية #القرآن_يتكلم #التدبر_حياة','https://anchor.fm/s/1022903e4/podcast/play/106198417/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-6-30%2Fc9da1f88-0d89-6223-46a4-64c4b18f147e.m4a',5040,'2025-07-30T06:32:38'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/106198417/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-6-30%2Fc9da1f88-0d89-6223-46a4-64c4b18f147e.m4a');
