SELECT p.id,'ميمونة بنت الحارث رضي الله عنها_ القصة الأخيرة ونصائح ذهبية للنساء🌷_ سلسلة أمهات المؤمنين','في حلقة دافئة من سلسلة نساء خالدات في قلب الأمة ، يحدّثنا المهندس علاء حامد عن ميمونة بنت الحارث ، آخر امرأة تزوجها النبي ﷺ، والتي عُرفت بتقواها وبرّها وصِلتها لأهلها. امرأة مباركة… اختارها النبي ﷺ في زمن صلح الحديبية، فكانت خاتمة أمهات المؤمنين. 🎙️ تقديم: المهندس علاء حامد #ميمونة_بنت_الحارث #أمهات_المؤمنين #علاء_حامد #سيرة_نبوية #البيت_النبوي #محاضرات_إسلامية #قصص_الصحابيات #نساء_في_الإسلام','https://anchor.fm/s/1022903e4/podcast/play/105732480/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-6-20%2F9099724f-3151-e857-2b46-cc96c63fae0b.mp3',4553,'2025-07-20T05:21:40'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/105732480/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-6-20%2F9099724f-3151-e857-2b46-cc96c63fae0b.mp3');
