SELECT p.id,'حفيدة هارون _ صفية بنت حيي بن أخطب رضى الله عنها _ قصة مؤثرة جداً 💞','في هذه الحلقة العميقة، يحدثنا المهندس علاء حامد عن صفية بنت حيي رضي الله عنها ، المرأة التي انتقلت من بيت النبوة اليهودي إلى بيت النبوة المحمدي، فأسلمت قلبًا وقالبًا. نتأمل كيف واجهت التحديات الاجتماعية والدينية بثبات، وكيف أحبها النبي ﷺ وكرّمها، حتى كانت من أمهات المؤمنين. 🔹 قصة تجمع بين التحول، والتسامح، والكرامة، وتُظهر عظمة الإسلام في احتواء القلوب. 🎙️ تقديم: المهندس علاء حامد 📚 ضمن سلسلة: نساء خالدات في قلب الأمة #صفية_بنت_حيي #أمهات_المؤمنين #علاء_حامد #قصص_إسلامية #سيرة_نبوية #البيت_النبوي #محاضرات_دينية #الصحابيات #الإسلام_والتسامح','https://anchor.fm/s/1022903e4/podcast/play/105714173/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-6-19%2F2192a4aa-314e-8690-650f-3d8649d635ff.mp3',4290,'2025-07-19T14:58:08'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/105714173/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-6-19%2F2192a4aa-314e-8690-650f-3d8649d635ff.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'حفصة بنت عمر رضي الله عنها _ كيف لا نعرف أمنا العظيمة وقصتها التربوية _ أمهات المؤمنين','في هذه الحلقة المميزة، يصحبنا المهندس علاء حامد في رحلة مع سيرة أم المؤمنين حفصة بنت عمر ، ابنة الفاروق، و"حافظة القرآن"، وزوجة النبي ﷺ. امرأة قوية الشخصية، عالمة، صاحبة رأي وثبات، اختارها الله لتكون من أهل بيت النبوة، وجعلها من نساء الجنة. 📖 قصة تُلهمنا بثبات العقيدة، وقوة المبادئ، ومكانة المرأة في الإسلام. 🎙️ تقديم: المهندس علاء حامد 📚 ضمن سلسلة: نساء خالدات في قلب الأمة #حفصة_بنت_عمر #أمهات_المؤمنين #علاء_حامد #سيرة_نبوية #نساء_في_الإسلام #الصحابيات #محاضرات_دينية #الفاروق_عمر #البيت_النبوي','https://anchor.fm/s/1022903e4/podcast/play/105714167/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-6-19%2Fa6c27ca5-1457-f4ae-3fa1-6126f9ae6418.mp3',4619,'2025-07-19T14:58:02'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/105714167/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-6-19%2Fa6c27ca5-1457-f4ae-3fa1-6126f9ae6418.mp3');
INSERT INTO episodes (podcast_id,title,description,audio_url,duration_seconds,published_at,plays_count)
SELECT p.id,'جويرية بنت الحارث وأم حبيبة رضى الله عنهما _ أحداث رائعة تسمعيها لأول مرة ❤️_ ( أمهات المؤمنين )','في هذا اللقاء المؤثر، يحدثنا المهندس علاء حامد عن سيرة أم المؤمنين جويرية بنت الحارث ، المرأة التي كان زواجها من النبي ﷺ بركة على قومها، فأعتق بسببها مئات من الأسرى. تعالوا نكتشف سيرة المرأة الذكية، العاقلة، التي أسلمت فثبتت، وكانت من أكثر الناس ذكرًا لله.#جويرية_بنت_الحارث #أمهات_المؤمنين #علاء_حامد #الرسول_وزوجاته #سيرة_نبوية #قصص_إسلامية #محاضرات_دينية #الصحابيات من دار الهجرة إلى بيت النبوة، يسرد لنا المهندس علاء حامد قصة أم المؤمنين أم حبيبة ، ابنة زعيم قريش أبي سفيان ، التي ثبتت على الإسلام رغم كل التحديات. نكتشف في هذه الحلقة دروسًا في الصبر والثبات، وموقفها المؤثر يوم زواجها من رسول الله ﷺ. 🔹 قصة امرأة عظيمة، عاشت الغربة، واختارت العقيدة. #أم_حبيبة #رملة_بنت_أبي_سفيان #أمهات_المؤمنين #علاء_حامد #الهجرة_إلى_الحبشة #سيرة_نبوية #قصص_إيمانية #محاضرات_إسلامية #الصحابيات','https://anchor.fm/s/1022903e4/podcast/play/105714162/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-6-19%2F09a924c2-b808-0ffb-51ef-1b3af7139f09.mp3',4996,'2025-07-19T14:57:53'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/105714162/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-6-19%2F09a924c2-b808-0ffb-51ef-1b3af7139f09.mp3');
