SELECT p.id,'عائشة رضي الله عنها (2) _ فن التعامل بين الزوجين ونصائح مهمة ❤️ _ ( أمهات المؤمنين )','بنت أبي بكر | أم المؤمنين والعالِمة الراوية في هذه الحلقة العطرة، يسرد لنا المهندس علاء حامد سيرة السيدة عائشة رضي الله عنها ، زوجة النبي ﷺ، وبنت الصديق، وأحد أعظم نساء الإسلام علمًا وفضلًا. 📌 نتعرّف على: نشأتها في بيت الصدّيق زواجها المبارك من النبي ﷺ مواقفها في بيت النبوة علمها الغزير ودورها في نقل السنة مكانتها بين الصحابة والتابعين 🎧 سرد مؤثر يناسب جميع الأعمار، ويُبرز الجوانب الروحية والفكرية من حياة واحدة من أمهات المؤمنين . #عائشة_بنت_أبي_بكر #أم_المؤمنين #قصص_الصحابة #الصحابيات #علاء_حامد #قصص_إسلامية #المرأة_في_الإسلام #بودكاست_إسلامي #عائشة_رضي_الله_عنها #سيرة_عائشة #أحاديث_عائشة #علم_الحديث #Alaa_Hamed #Islamic_History','https://anchor.fm/s/1022903e4/podcast/play/105704140/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-6-19%2F943698b7-b8ba-372e-7c5f-6c6d3571e9af.mp3',4308,'2025-07-19T05:27:25'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/105704140/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-6-19%2F943698b7-b8ba-372e-7c5f-6c6d3571e9af.mp3');
