SELECT p.id,'(خديجة بنت خويلد رضي الله عنها 🌷 _ أمنا الجميلة وتفاصيل رائعة _ (أمهات المؤمنين','خديجة بنت خويلد | سيدة نساء قريش وأول المؤمنات في هذه الحلقة المؤثرة، يصحبنا المهندس علاء حامد في رحلة عبر سيرة السيدة خديجة رضي الله عنها ، أول من آمنت برسالة النبي ﷺ، ووقفت بجانبه في أشد لحظات الدعوة. 💠 نتعرّف على: نسبها الشريف ومكانتها في قريش زواجها من النبي ﷺ ودعمها العظيم له دورها في بدايات الإسلام وصبرها في سبيل الله وفاتها التي جعلت النبي ﷺ يسمي العام بـ"عام الحزن" 🎧 استمع إلى القصة بصوت دافئ وسرد مبسّط يلامس القلوب، ضمن سلسلة السير العطرة للصحابيات والأنبياء. #خديجة_بنت_خويلد #السيدة_خديجة #أمهات_المؤمنين #قصص_الصحابة #علاء_حامد #قصص_إسلامية #المرأة_في_الإسلام #بودكاست_إسلامي #قصص_الصحابيات #خديجة_رضي_الله_عنها #سيرة_خديجة #Quranic_Stories #Islamic_Legacy #Alaa_Hamed','https://anchor.fm/s/1022903e4/podcast/play/105704094/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-6-19%2F82886970-9683-04d2-55c1-58bf9f1c131d.mp3',5218,'2025-07-19T05:23:31'::timestamptz,0 FROM podcasts p WHERE p.title='السيرة النبوية للمهندس علاء حامد' AND NOT EXISTS (SELECT 1 FROM episodes e WHERE e.podcast_id=p.id AND e.audio_url='https://anchor.fm/s/1022903e4/podcast/play/105704094/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-6-19%2F82886970-9683-04d2-55c1-58bf9f1c131d.mp3');
